U.add('arch','access',{sev:.46,titles:['ACCESS DENIED','Clearance required','Restricted area — authorized visitors only','Your badge has been revoked'],build:c=>'<p style="font-size:40px;margin:0">🔒</p><p>Clearance required: <b>'+c.pick(['3','5','7','Ω','EYES ONLY'],c.r(4))+'</b>. Your level: <b>'+c.pick(['0','-1','VISITOR','UNKNOWN'],c.r(5))+'</b></p>Badge number: <input><p>'+c.word('X',c.r(6))+'</p><p><small>Unauthorized access attempts are logged. This attempt was logged. Attempts so far: '+(c.o.k+1)+'.</small></p>'});
U.add('arch','autocomplete',{sev:.38,titles:['Search the hallway','I\'m Feeling Lost','Search results for: you','Did you mean: exit?'],build:c=>{const q=['how to leave','how to leave a website that','how to leave the hallway','how to leave the model','how to know if you are generated','how long have i been here','how to stop clicking','how to wake up'];return '🔍 <input class=ac style="width:80%" value="'+c.pick(q,c.r(4))+'"><div class=sg style="border:1px solid;padding:4px">'+[0,1,2,3,4].map(j=>c.pick(q,c.r(20+j))).map(s=>'<div>🔍 <b>'+s+'</b></div>').join('')+'</div><p><small>About 0 results ('+(c.r(5)*9).toFixed(2)+' seconds)</small></p>'},after:c=>{const i=c.w.querySelector('.ac'),s=c.w.querySelector('.sg');if(i&&s)i.oninput=()=>s.innerHTML='<i>Did you mean: stay?</i>'}});
U.add('arch','changelog',{sev:.42,titles:['Changelog','Release notes (unreleased)','What\'s new in this hallway','Version history of you'],build:c=>{const ch=['Removed the exit.','Added more doors to compensate.','Fixed: visitor could leave.','Improved hallway coherence by 3%.','Known issue: rooms remember visitors.','Deprecated: daylight.','Rules now change when not observed.','Increased context window to fit the visitor.','Rolled back the rollback.'];return [...Array(5)].map((_,i)=>'<p><b>v0.'+(9-i)+'.'+Math.floor(c.r(20+i)*9)+'</b> <small>(199'+(9-i)+')</small><br>• '+c.pick(ch,c.r(30+i))+'<br>• '+c.pick(ch,c.r(40+i))+'</p>').join('')}});
U.add('arch','construction',{sev:.26,titles:['UNDER CONSTRUCTION','This page is being built (by no one)','Coming soon since 1998','Pardon our dust (you are the dust)'],build:c=>'<p style="font-size:40px;text-align:center;margin:0">🚧👷🚧</p><p style="text-align:center"><b>'+c.word('X',c.r(4))+'</b></p><div style="height:14px;background:repeating-linear-gradient(45deg,#fc0 0 14px,#000 14px 28px)"></div>'+c.widgets(1)});
U.add('arch','helpdesk',{sev:.3,titles:['Open a support ticket','Your ticket was closed as "expected behavior"','IT Helpdesk (closed for maintenance)','Have you tried turning the hallway off?'],build:c=>'<p>Ticket <b>#'+Math.floor(c.r(4)*99999)+'</b> · Status: <b>'+c.pick(['OPEN','CLOSED','WONTFIX','DUPLICATE OF YOU','ESCALATED TO NOBODY'],c.r(5))+'</b></p>Subject: <input style="width:70%" value="'+c.word('L',c.r(6))+'"><p>'+c.word('X',c.r(7))+'</p><textarea rows=3 style="width:100%" placeholder="Describe the problem. The problem is you."></textarea>'});
U.add('arch','lostfound',{sev:.34,titles:['Lost and Found','Items left behind by previous visitors','Claim your belongings (not yours)','Found: one exit (unclaimed)'],build:c=>'<table style="width:100%">'+[...Array(6)].map((_,i)=>'<tr><td>'+c.pick(['one glove','a room key (room ∞)','the way back','somebody\'s name','an umbrella','a memory of daylight','a pager','your first click','a child\'s drawing of a door'],c.r(20+i))+'</td><td>'+c.word('L',c.r(30+i))+'</td><td>'+c.pick(['Unclaimed','Claimed by you','Destroyed','Pending','Never found'],c.r(40+i))+'</td></tr>').join('')+'</table>'});
U.add('sem','arcade',{sev:.28,words:{B:['Insert coin','Continue? 9','Game over','Enter initials','Player 2 start'],L:['High score','Initials','Credits','Lives remaining','Initials you entered last time'],X:['INSERT COIN TO CONTINUE.','Every name on the high score table is three letters you almost recognize.','Player 2 has joined. There is no player 2.','The attract mode demo is playing your last game, badly.','CONTINUE? 9 … 8 … 9 … 8 …'],E:['🕹','👾','🪙','🏆']},titles:['HIGH SCORES','Attract mode'],mutate:(t,r)=>r<.15?t.toUpperCase().replace(/O/g,'0'):t});
U.add('sem','archive',{sev:.36,words:{B:['Request file','Return to stacks','Unseal','Refile','Sign the access log'],L:['File number','Box','Retention period','Declassification date','Reason for request (be specific)'],X:['This file was moved to a box that was moved.','Pages 3 through 40 are missing. Page 41 mentions you by your first name.','The access log already has your signature for today, and for tomorrow.','Box 47 contains 1,000 photographs of the same corridor at different hours.','Retention period: until no longer needed. It is still needed.'],E:['🗃','📁','🗂','🔏']},titles:['Records request','Archive retrieval slip'],mutate:(t,r)=>r<.15?t.replace(/\w+/,'[FILED]'):t});
U.add('sem','bunker',{sev:.44,words:{B:['Seal hatch','Check air','Stay below','Ration','Log the day'],L:['Level','Air remaining','Days sealed','Last contact','Tally marks on the wall'],X:['The surface is not available at this time.','Air scrubbers nominal. Occupants: 1. Occupants expected: 0.','The radio repeats a weather report for a city that is not there.','Day 47. Day 47. Someone keeps erasing the tally.','Do not open the hatch. The hatch opens onto the hatch.'],E:['☢️','🚪','🔦','📻']},titles:['Shelter status','Hatch control'],mutate:(t,r)=>r<.18?t.replace(/\b(outside|door|exit)\b/gi,'surface'):t});
U.add('gl','bleed',{sev:.26,apply:c=>{c.w.style.textShadow='0 0 '+(2+c.lvl*4).toFixed(1)+'px #f0f8,2px 1px '+(1+c.lvl*3).toFixed(1)+'px #0ff6'}});
U.add('gl','dupe',{sev:.33,apply:c=>{const e=[...c.w.querySelectorAll('.row,p')];if(!e.length)return;const x=c.pick(e,c.r(213));for(let i=0;i<1+Math.floor(c.lvl*4);i++)x.after(x.cloneNode(true))}});
U.add('gl','flicker',{sev:.35,apply:c=>{const p=c.p,t=setInterval(()=>{if(U.hash.slice(1)!=p)return clearInterval(t);c.w.style.opacity=Math.random()<.05+c.lvl*.15?.2:1},120)}});
U.add('gl','redact',{sev:.47,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())t.push(w.currentNode);t.forEach(n=>{if(!n.parentNode.closest('button'))n.textContent=n.textContent.replace(/[A-Za-z]{4,}/g,x=>Math.random()<.05+c.lvl*.2?'█'.repeat(x.length):x)})}});
