U.add('gl','stutter',{sev:.4,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())t.push(w.currentNode);t.forEach(n=>n.textContent=n.textContent.replace(/\b[A-Za-z]{2,}\b/g,x=>Math.random()<.04+c.lvl*.12?x+' '+x:x))}});
U.add('snd','heart',{sev:.44,play:(a,o,r)=>{const f0=45+r(300)*25,gap=.25+r(301)*.1,bpm=50+r(302)*40,ty=r(303)<.7?'sine':'triangle',beat=(s,A)=>{const x=a.createOscillator(),g=a.createGain();x.type=ty;x.frequency.setValueAtTime(f0,s);x.frequency.exponentialRampToValueAtTime(f0*.6,s+.15);g.gain.setValueAtTime(A,s);g.gain.exponentialRampToValueAtTime(.001,s+.25);x.connect(g).connect(o);x.start(s);x.stop(s+.3)},t=setInterval(()=>{const s=a.currentTime;beat(s,.3);beat(s+gap,.2)},60000/bpm);return()=>clearInterval(t)}});
U.add('snd','phone',{sev:.28,play:(a,o,r)=>{const f=a.createBiquadFilter(),g=a.createGain(),ty=r(300)<.6?'sine':'square',v=[440,480].map(h=>{const x=a.createOscillator();x.type=ty;x.frequency.value=h*(1+(r(301)-.5)*.2);x.connect(f);x.start();return x});f.type='lowpass';f.frequency.value=600+r(302)*900;g.gain.value=0;f.connect(g).connect(o);const on=1+r(303),off=2+r(304)*3,dbl=r(305)<.5,A=ty=='sine'?.06:.03;let dead=0,to;const ring=()=>{if(dead)return;const t0=a.currentTime;g.gain.setValueAtTime(A,t0);g.gain.setValueAtTime(0,t0+on*(dbl?.4:1));if(dbl){g.gain.setValueAtTime(A,t0+on*.55);g.gain.setValueAtTime(0,t0+on)}to=setTimeout(ring,(on+off)*1000)};to=setTimeout(ring,1000+r(306)*3000);return()=>{dead=1;clearTimeout(to);v.forEach(x=>x.stop())}}});
U.add('snd','tape',{sev:.36,play:(a,o,r)=>{const n=a.createBufferSource(),b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;n.buffer=b;n.loop=true;const hp=a.createBiquadFilter(),hg=a.createGain();hp.type='highpass';hp.frequency.value=2000+r(300)*3000;hg.gain.value=.04+r(301)*.04;n.connect(hp).connect(hg).connect(o);const x=a.createOscillator(),g=a.createGain(),w=a.createOscillator(),wg=a.createGain(),fl=a.createOscillator(),fg=a.createGain();x.type=r(302)<.6?'sine':'triangle';x.frequency.value=150+r(303)*180;g.gain.value=.1;w.frequency.value=.2+r(304);wg.gain.value=10+r(305)*30;fl.frequency.value=6+r(306)*6;fg.gain.value=3+r(307)*5;w.connect(wg).connect(x.detune);fl.connect(fg).connect(x.detune);x.connect(g).connect(o);[n,x,w,fl].forEach(s=>s.start());return()=>[n,x,w,fl].forEach(s=>s.stop())}});